// Existing n8n rows use MONTHLY_MAINTENANCE; the operations contract uses lowercase.
return $input.all().map((item) => ({
  json: { ...item.json, reportType: String(item.json?.reportType ?? '').trim().toLowerCase() }
}));

// Read-only normalizer for the existing monthly-report Data Table.
// It never exposes R2 object keys/locators and never changes a report row.
// The old field pdfDriveFileId is an R2 object key; use it only to determine
// private PDF availability. Do not include it in any evidence payload.

const allowedStates = new Set(['DRAFT', 'APPROVED', 'SENDING', 'SENT', 'REJECTED', 'SEND_FAILED']);
const allowedStatus = new Set(['GREEN', 'AMBER', 'RED', 'NO_DATA', 'UNKNOWN']);
const allowedSeverity = new Set(['info', 'warning', 'critical', 'none']);
const clean = (value) => String(value ?? '').trim();
const iso = (value) => {
  const text = clean(value);
  return Number.isFinite(Date.parse(text)) ? new Date(text).toISOString() : null;
};
const safeMonth = (value) => /^\d{4}-\d{2}$/.test(clean(value)) ? clean(value) : null;

const records = [];
for (const item of $input.all()) {
  const row = item.json ?? {};
  const reportMonth = safeMonth(row.reportMonth);
  const reportType = clean(row.reportType) || 'monthly_maintenance';
  const documentStatus = clean(row.documentStatus).toUpperCase();
  if (!reportMonth || !allowedStates.has(documentStatus) || reportType !== 'monthly_maintenance') continue;

  const reportKey = `cavetta.monthly_maintenance.${reportMonth}`;
  const overallCandidate = clean(row.overallResult).toUpperCase();
  const severityCandidate = clean(row.severity).toLowerCase();
  const generatedAt = iso(row.generatedAt);
  const approvedAt = iso(row.approvedAt);
  const rejectedAt = iso(row.rejectedAt);
  const sendingStartedAt = iso(row.sendingStartedAt);
  const sentAt = iso(row.sentAt);
  const pdfGeneratedAt = iso(row.pdfGeneratedAt);
  const attempts = Number(row.sendAttemptCount);
  const stateStamp = sentAt || sendingStartedAt || approvedAt || rejectedAt || generatedAt || documentStatus;
  const payload = {
    reportKey, reportMonth, reportType, documentStatus,
    findingCountsBySeverity: {},
    pdfAvailable: Boolean(clean(row.pdfDriveFileId) && clean(row.pdfFileName) && pdfGeneratedAt),
    sendAttemptCount: Number.isInteger(attempts) && attempts >= 0 && attempts <= 1000 ? attempts : 0
  };
  if (allowedStatus.has(overallCandidate)) payload.overallStatus = overallCandidate;
  if (generatedAt) payload.generatedAt = generatedAt;
  if (pdfGeneratedAt) payload.generatedAt = payload.generatedAt ?? pdfGeneratedAt;
  if (approvedAt) payload.approvedAt = approvedAt;
  if (rejectedAt) payload.rejectedAt = rejectedAt;
  if (sendingStartedAt) payload.sendingStartedAt = sendingStartedAt;
  if (sentAt) payload.sentAt = sentAt;

  records.push({
    contractVersion: '1.0', recordType: 'report_summary',
    idempotencyKey: `report-summary-${reportKey}-${documentStatus}-${stateStamp}`.slice(0, 160),
    environmentKey: 'production', sourceSystem: 'n8n',
    observedAt: new Date().toISOString(), publishedAt: new Date().toISOString(),
    freshUntil: new Date(Date.now() + 35 * 24 * 60 * 60 * 1000).toISOString(),
    status: allowedStatus.has(overallCandidate) ? overallCandidate : 'UNKNOWN',
    severity: allowedSeverity.has(severityCandidate) ? severityCandidate : 'none',
    correlationKey: reportKey, payload
  });
}

return [{ json: { publisherKey: 'cavetta-production-n8n', records, recordCount: records.length } }];
